import re

def encode_amount(dollars: str) -> str:
    # Remove any whitespace
    dollars = dollars.strip()

    # Determine sign
    if dollars.startswith('-'):
        sign = '-'
        dollars = dollars[1:]
    else:
        sign = '+'
        if dollars.startswith('+'):
            dollars = dollars[1:]

    # Split into dollars and cents
    if '.' in dollars:
        dollars_part, cents_part = dollars.split('.', 1)
    else:
        dollars_part = dollars
        cents_part = ''

    # Validate and normalize
    if dollars_part == '':
        dollars_part = '0'
    if cents_part == '':
        cents_part = '00'
    elif len(cents_part) == 1:
        cents_part += '0'
    elif len(cents_part) > 2:
        raise ValueError("Invalid cents precision")

    # Validate digits
    if not re.match(r'^\d+$', dollars_part) or not re.match(r'^\d{2}$', cents_part):
        raise ValueError("Invalid amount format")

    # Calculate total cents (minor units)
    total_cents = int(dollars_part) * 100 + int(cents_part)
    digits = str(total_cents)

    # Calculate check digit: sum of digits mod 10
    check = sum(int(d) for d in digits) % 10

    return f"{sign}{digits}#{check}"

