import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using the ledger module's post function.

    Args:
        acct: Account to post to
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        The entry id from posting the transfer
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post an entry to the ledger with account, amount, and memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transfer"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason '{reason}' using the ledger post function. Return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
