```python
def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the wire format.

    The wire format is the signed integer number of cents, as a string.
    Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0.00'   -> '0'
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("multiple decimal points")
    else:
        whole, frac = s, ""

    # Allow forms like '.5' or '5.'
    if whole == "" and frac == "":
        raise ValueError("missing digits")

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError(f"invalid whole part: {whole!r}")
    if frac != "" and not frac.isdigit():
        raise ValueError(f"invalid fractional part: {frac!r}")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        # Reject sub-cent precision rather than silently truncating.
        if frac[2:].strip("0"):
            raise ValueError("sub-cent precision not supported")
        frac = frac[:2]
    frac = (frac + "00")[:2]

    cents = sign * (int(whole) * 100 + int(frac))
    return str(cents)
