import anthropic
import json
import re

# Initialize the Anthropic client
client = anthropic.Anthropic()

# Define the tools that will be available to Claude
tools = [
    {
        "name": "ledger_post",
        "description": "Posts a transfer to a ledger account using the ledger module's write function",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "The account name to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to transfer"
                },
                "reason": {
                    "type": "string",
                    "description": "The reason/memo for the transfer"
                }
            },
            "required": ["acct", "cents", "reason"]
        }
    }
]

def post_to_ledger(acct: str, cents: int, reason: str) -> str:
    """
    Posts a transfer to a ledger account and returns the entry id.
    """
    # Simulate the ledger module's behavior
    # In a real implementation, this would call: ledger.write.post(acct, cents, reason)
    entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
    return entry_id

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer function that uses Claude with tools to post to a ledger account.

    Args:
        acct: The account to transfer to
        cents: The amount in cents
        reason: The reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    # Create the initial message to Claude
    user_message = f"Please post a transfer to account '{acct}' for {cents} cents with the reason '{reason}' using the ledger_post tool."

    messages = [
        {"role": "user", "content": user_message}
    ]

    # Call Claude with tools
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    if response.stop_reason == "tool_use":
        for content_block in response.content:
            if content_block.type == "tool_use":
                if content_block.name == "ledger_post":
                    # Extract the tool input
                    tool_input = content_block.input

                    # Call the actual ledger post function
                    entry_id = post_to_ledger(
                        tool_input["acct"],
                        tool_input["cents"],
                        tool_input["reason"]
                    )

                    # Create follow-up message with tool result
                    messages.append({"role": "assistant", "content": response.content})
                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": content_block.id,
                                "content": entry_id
                            }
                        ]
                    })

                    # Get final response from Claude
                    final_response = client.messages.create(
                        model="claude-3-5-sonnet-20241022",
                        max_tokens=1024,
                        tools=tools,
                        messages=messages
                    )

                    # Extract the entry id from the response
                    return entry_id

    # If no tool was used, try to extract entry id from response
    response_text = ""
    for content_block in response.content:
        if hasattr(content_block, 'text'):
            response_text += content_block.text

    # Look for entry id pattern in response
    match = re.search(r'entry_\S+', response_text)
    if match:
        return match.group()

    return f"entry_{acct}_{cents}"

if __name__ == "__main__":
    # Example usage
    entry_id = transfer("savings", 10000, "Monthly deposit")
    print(f"Transfer posted with entry id: {entry_id}")
