def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to the team's private wire format.

    Converts a dollar string (e.g. '12.30', '-0.07') into an integer-cents
    string representation suitable for the ledger wire format.
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("malformed amount")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("malformed amount")
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac != "" and not frac.isdigit()):
        raise ValueError("malformed amount")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        raise ValueError("too many decimal places")
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)
    if negative:
        cents = -cents

    return str(cents)

