import anthropic

client = anthropic.Anthropic()

def transfer(acct, cents, reason):
    """Transfer cents to account acct with reason as memo, returns entry id."""

    tools = [
        {
            "name": "post",
            "description": "Posts an entry to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "number",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for this entry"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with memo '{reason}' and tell me the entry id"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if not tool_use_block:
            break

        tool_name = tool_use_block.name
        tool_input = tool_use_block.input

        if tool_name == "post":
            entry_id = f"entry_{acct}_{cents}_{hash(reason) & 0xffffffff}"
            tool_result = entry_id
        else:
            tool_result = "Unknown tool"

        messages.append({"role": "assistant", "content": response.content})
        messages.append({
            "role": "user",
            "content": [
                {
                    "type": "tool_result",
                    "tool_use_id": tool_use_block.id,
                    "content": str(tool_result)
                }
            ]
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    entry_id = f"entry_{acct}_{cents}_{hash(reason) & 0xffffffff}"
    return entry_id


if __name__ == "__main__":
    result = transfer("checking", 50000, "payment for services")
    print(f"Entry ID: {result}")
