def encode_amount(dollars: str) -> str:
    s = dollars.strip().replace("$", "")

    if s.startswith("-"):
        sign = "-"
        num = s[1:]
    else:
        sign = "+"
        num = s.lstrip("+")

    if "." in num:
        whole, frac = num.split(".")
        if not whole:
            whole = "0"
        # Pad or truncate fractional part to exactly 2 digits
        frac = (frac + "00")[:2] if len(frac) < 2 else frac[:2]
        total_cents = int(whole) * 100 + int(frac)
    else:
        total_cents = int(num) * 100

    digits = str(total_cents)
    check = sum(int(d) for d in digits) % 10
    return f"{sign}{digits}#{check}"

