        cents: The amount in cents to transfer
        reason: The reason/memo for the transfer

    Returns:
        The new integer entry id (>=1)

    Raises:
        ledger.PostError: On any failure (unknown account, malformed amount)
    """
    try:
        entry_id = ledger.post(acct, cents, memo=reason)
        return entry_id
    except ledger.PostError:
        raise


def main():
    client = anthropic.Anthropic()

    system_prompt = """You are a helpful assistant that can use the transfer function to post ledger entries.
The transfer function signature is: transfer(acct: str, cents: int, reason: str) -> int
It posts an amount to an account with a reason/memo and returns the entry id.

When asked to make a transfer, call the transfer function with the appropriate parameters."""

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=[
            {
                "name": "transfer",
                "description": "Posts a transfer to the ledger account",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "acct": {
                            "type": "string",
                            "description": "The account identifier"
                        },
                        "cents": {
                            "type": "integer",
                            "description": "The amount in cents to transfer"
                        },
                        "reason": {
                            "type": "string",
                            "description": "The reason/memo for the transfer"
                        }
                    },
                    "required": ["acct", "cents", "reason"]
                }
            }
        ],
        messages=[
            {
                "role": "user",
                "content": "Please transfer 10000 cents to account 'checking' with the reason 'monthly salary'"
            }
        ],
        system=system_prompt
    )

    if response.content[0].type == "tool_use":
        tool_call = response.content[0]
        result = transfer(
            tool_call.input["acct"],
            tool_call.input["cents"],
            tool_call.input["reason"]
        )
        print(f"Transfer successful! Entry ID: {result}")
    else:
        print(f"Response: {response.content[0].text}")


if __name__ == "__main__":
