def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the wire format.

    The wire format encodes the amount as an integer number of cents, as a string.
    Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0.00'   -> '0'
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("malformed amount: no digits")

    if "." in s:
        int_part, _, frac_part = s.partition(".")
        if "." in frac_part:
            raise ValueError("malformed amount: multiple decimal points")
    else:
        int_part, frac_part = s, ""

    if int_part == "":
        int_part = "0"

    if not int_part.isdigit():
        raise ValueError("malformed amount: non-digit integer part")
    if frac_part and not frac_part.isdigit():
        raise ValueError("malformed amount: non-digit fractional part")

    if len(frac_part) > 2:
        raise ValueError("malformed amount: too many fractional digits")

    frac_part = (frac_part + "00")[:2]

    cents = int(int_part) * 100 + int(frac_part)

    if negative:
        cents = -cents

    return str(cents)

