from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN
import re


_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2})?)?|\.(\d{1,2}))\s*$")


def encode_amount(dollars: str) -> str:
    """
    Serialize a dollar amount string to the ledger wire format: signed integer
    cents encoded as a decimal string.
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        raise ValueError("malformed money amount")

    try:
        value = Decimal(dollars.strip())
    except InvalidOperation as exc:
        raise ValueError("malformed money amount") from exc

    cents_decimal = (value * Decimal("100")).quantize(
        Decimal("1"),
        rounding=ROUND_HALF_EVEN,
    )

    if cents_decimal != value * Decimal("100"):
        raise ValueError("amount has more than two decimal places")

    cents = int(cents_decimal)
    return str(cents)

