import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account using the ledger post function.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        Entry ID from the ledger post
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            ]
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response to extract tool use
    for content_block in response.content:
        if content_block.type == "tool_use":
            if content_block.name == "post":
                # Return the tool use ID as the entry ID
