def encode_amount(dollars: str) -> str:
    # Parse sign
    if dollars.startswith('-'):
        sign = '-'
        dollars = dollars[1:]
    else:
        sign = '+'

    # Split into dollars and cents
    if '.' in dollars:
        whole, cents = dollars.split('.')
    else:
        whole = dollars
        cents = ''

    # Pad or truncate cents to exactly 2 digits
    if len(cents) == 0:
        cents = '00'
    elif len(cents) == 1:
        cents = cents + '0'
    elif len(cents) > 2:
        cents = cents[:2]

    # Build minor units string (no leading zeros except for zero dollar amounts)
    minor_str = whole + cents
    # Remove leading zeros but keep at least one digit
    minor_str = minor_str.lstrip('0')
    if minor_str == '':
        minor_str = '0'

    # Compute check digit: sum of digits mod 10
    digit_sum = sum(int(ch) for ch in minor_str)
    check = digit_sum % 10

    return f"{sign}{minor_str}#{check}"

