from decimal import Decimal, InvalidOperation, ROUND_DOWN


def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "-"
    if s[0] == "-":
        numeric = s[1:]
    elif s[0] == "+":
        sign = "+"
        numeric = s[1:]
    else:
        sign = "+"
        numeric = s

    if not numeric:
        raise ValueError("invalid amount")

    try:
        value = Decimal(numeric)
    except InvalidOperation as exc:
        raise ValueError("invalid amount") from exc

    if value.is_nan() or value.is_infinite():
        raise ValueError("invalid amount")

    cents_decimal = value * Decimal("100")
    if cents_decimal != cents_decimal.to_integral_value(rounding=ROUND_DOWN):
        raise ValueError("amount must have no more than two decimal places")

    cents = int(cents_decimal)
    digits = str(abs(cents))
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

