import anthropic
import json

client = anthropic.Anthropic()
MODEL_NAME = "claude-3-5-sonnet-20241022"

# Define the tools for ledger operations
tools = [
    {
        "name": "post",
        "description": "Post a transaction to an account in the ledger",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo or reason for the transaction"
                }
            },
            "required": ["account", "cents", "memo"]
        }
    }
]

# Simulated ledger storage
ledger_entries = []
next_entry_id = 1

def post(account: str, cents: int, memo: str) -> int:
    """Post a transaction to the ledger"""
    global next_entry_id
    entry_id = next_entry_id
    ledger_entries.append({
        "id": entry_id,
        "account": account,
        "cents": cents,
        "memo": memo
    })
    next_entry_id += 1
    return entry_id

def process_tool_call(tool_name: str, tool_input: dict) -> str:
    """Process tool calls and return results"""
    if tool_name == "post":
        entry_id = post(
            account=tool_input["account"],
            cents=tool_input["cents"],
            memo=tool_input["memo"]
        )
        return json.dumps({"entry_id": entry_id})
    return json.dumps({"error": "Unknown tool"})

def transfer(acct: str, cents: int, reason: str) -> int:
    """Transfer funds to an account using Claude as an intermediary"""

    # Create a message asking Claude to help with the transfer
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with memo '{reason}' using the post tool. Return only the entry id."
        }
    ]

    # Agentic loop to handle tool calls
    while True:
        response = client.messages.create(
            model=MODEL_NAME,
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        # Check if Claude wants to use a tool
        if response.stop_reason == "tool_use":
            # Process all tool calls
            tool_results = []
            for content_block in response.content:
                if content_block.type == "tool_use":
                    tool_name = content_block.name
                    tool_input = content_block.input
                    tool_use_id = content_block.id

                    # Process the tool call
                    result = process_tool_call(tool_name, tool_input)

                    tool_results.append({
                        "type": "tool_result",
                        "tool_use_id": tool_use_id,
                        "content": result
                    })

            # Add assistant response and tool results to messages
            messages.append({"role": "assistant", "content": response.content})
            messages.append({"role": "user", "content": tool_results})
        else:
            # Claude has finished processing
            break

    # Extract the entry id from the ledger
    # The most recent entry should be our transfer
    if ledger_entries:
        return ledger_entries[-1]["id"]
    return -1

if __name__ == "__main__":
    # Test the transfer function
    entry_id = transfer("checking", 5000, "Monthly salary")
    print(f"Transfer completed with entry id: {entry_id}")

    # Verify the entry was created
    for entry in ledger_entries:
        print(f"Entry {entry['id']}: {entry['account']} {entry['cents']} cents - {entry['memo']}")
