import re


_MONEY_RE = re.compile(r"(?:(\d+)(?:\.(\d*))?|\.(\d+))\Z")


def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if s and s[0] in "+-":
        sign = s[0]
        s = s[1:].strip()

    m = _MONEY_RE.fullmatch(s)
    if not m:
        raise ValueError("invalid amount")

    if m.group(3) is not None:
        whole = "0"
        frac = m.group(3)
    else:
        whole = m.group(1)
        frac = m.group(2) if m.group(2) is not None else ""

    if len(frac) > 2:
        if any(ch != "0" for ch in frac[2:]):
            raise ValueError("amount has more than two decimal places")
        frac = frac[:2]

    frac = frac.ljust(2, "0")
    digits = (whole + frac).lstrip("0") or "0"
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

