def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if s.startswith("-"):
        sign = "-"
        s = s[1:]
    else:
        sign = "+"
        if s.startswith("+"):
            s = s[1:]

    if "." in s:
        whole, frac = s.split(".", 1)
        if not whole:
            whole = "0"
        if len(frac) < 2:
            frac = frac.ljust(2, "0")
        elif len(frac) > 2:
            frac = frac[:2]
    else:
