def encode_amount(dollars: str) -> str:
    # strip whitespace
    s = dollars.strip()

    # determine sign
    sign = ""
    if s.startswith("-"):
        sign = "-"
        s = s[1:]

    # split into integer and fractional parts
    if "." in s:
        int_part, frac_part = s.split(".", 1)
    else:
        int_part = s
        frac_part = ""

    # validate and normalize integer part
    if int_part == "":
        int_part = "0"
    else:
        # remove leading zeros, but keep at least one digit
        int_part = int_part.lstrip("0") or "0"

    # validate and normalize fractional part (pads to 2 digits, truncates extras)
    if frac_part == "":
        frac_part = "00"
    else:
        # only keep the first two digits
        if len(frac_part) > 2:
            frac_part = frac_part[:2]
        elif len(frac_part) == 1:
            frac_part = frac_part + "0"
        # if 0 length, already handled

    # validate that both parts are purely digits
    if not int_part.isdigit() or not frac_part.isdigit():
        raise ValueError("Invalid amount format")

    # combine
    result = f"{sign}{int_part}.{frac_part}"
    return result

