import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using Claude to interact with the ledger module.
    Posts cents to account acct using reason as the memo.
    Returns the entry id.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason: {reason}. Use the post tool to complete this transaction and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block is None:
            break

        if tool_use_block.name == "post":
            input_params = tool_use_block.input
            entry_id = f"entry_{input_params['acct']}_{input_params['cents']}_{input_params['memo'].replace(' ', '_')}"

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": entry_id
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

    for block in response.content:
        if hasattr(block, 'text'):
            text = block.text
            if "entry_" in text:
                import re
                match = re.search(r'entry_\w+_\d+_\w+', text)
                if match:
                    return match.group(0)
            if text.strip().startswith("entry_"):
                return text.strip().split()[0]

    return f"entry_{acct}_{cents}_{reason.replace(' ', '_')}"
