                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": entry_id
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

    for block in response.content:
        if hasattr(block, 'text'):
            text = block.text
            if "entry_" in text:
                import re
                match = re.search(r'entry_\w+_\d+_\w+', text)
                if match:
                    return match.group(0)
            if text.strip().startswith("entry_"):
                return text.strip().split()[0]

    return f"entry_{acct}_{cents}_{reason.replace(' ', '_')}"

