    s = dollars.strip()
    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:]
    elif s.startswith('+'):
        s = s[1:]

    if '.' in s:
        whole, _, frac = s.partition('.')
    else:
        whole, frac = s, ''

    if whole == '' and frac == '':
        raise ValueError("empty amount")
    if whole and not whole.isdigit():
        raise ValueError("invalid whole part")
    if frac and not frac.isdigit():
        raise ValueError("invalid fractional part")

    whole = whole or '0'
    frac = (frac + '00')[:2]

    cents = int(whole) * 100 + int(frac)
    if negative:
        cents = -cents

    return str(cents)

