    if s.count(".") > 1:
        raise ValueError("malformed amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("malformed amount")

    if len(frac) > 2:
        raise ValueError("too many fractional digits")

    frac = frac.ljust(2, "0")
    cents = int(whole) * 100 + int(frac or "0")

    if sign < 0 and cents:
        cents = -cents

    return str(cents)

