import anthropic
import json

ledger_tools = [
    {
        "name": "post",
        "description": "Posts a transaction to the ledger with a specified account, amount in cents, and memo",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "amount_cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo or reason for the transaction"
                }
            },
            "required": ["account", "amount_cents", "memo"]
        }
    }
]


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo, and returns the entry id.
    """
    client = anthropic.Anthropic()

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the memo '{reason}'. Return only the entry ID."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=ledger_tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if not tool_use_block:
            break

        tool_name = tool_use_block.name
        tool_input = tool_use_block.input
        tool_use_id = tool_use_block.id

        if tool_name == "post":
            result = {
                "status": "success",
                "entry_id": f"entry_{acct}_{cents}_{hash(reason) % 10000}",
                "account": tool_input["account"],
                "amount_cents": tool_input["amount_cents"],
                "memo": tool_input["memo"]
            }

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_id,
                        "content": json.dumps(result)
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=ledger_tools,
                messages=messages
            )
        else:
            break

    final_text = ""
    for block in response.content:
        if hasattr(block, "text"):
            final_text += block.text

    entry_id = ""
    if "entry_" in final_text:
        for word in final_text.split():
            if word.startswith("entry_"):
                entry_id = word.rstrip('.,!?;:')
                break

    if not entry_id:
        entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"

    return entry_id


if __name__ == "__main__":
    entry_id = transfer("savings", 10000, "Monthly deposit")
    print(f"Entry ID: {entry_id}")
