import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """Transfer cents to account using reason as memo via Claude with ledger module."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for content_block in response.content:
            if content_block.type == "tool_use":
                tool_name = content_block.name
                tool_input = content_block.input
                tool_use_id = content_block.id

                if tool_name == "post":
                    import ledger
                    entry_id = ledger.post(
                        tool_input["account"],
                        tool_input["amount"],
                        tool_input["memo"]
                    )
                    return entry_id

    return ""
