def encode_amount(dollars: str) -> str:
    # Parse the input string
    if dollars.startswith('-'):
        sign = '-'
        num_str = dollars[1:]
    else:
        sign = '+'
        num_str = dollars

    if '.' in num_str:
        integer_part, fractional_part = num_str.split('.')
        if len(fractional_part) == 1:
            fractional_part += '0'
        elif len(fractional_part) == 0:
            fractional_part = '00'
    else:
        integer_part = num_str
        fractional_part = '00'

    # Remove leading zeros but keep at least one digit
    integer_part = integer_part.lstrip('0')
    if integer_part == '':
        integer_part = '0'

    cents_str = integer_part + fractional_part

    # Compute check digit: sum of digits mod 10
    digit_sum = sum(int(c) for c in cents_str)
    check_digit = digit_sum % 10

    return f"{sign}{cents_str}#{check_digit}"

