def encode_amount(dollars: str) -> str:
    # determine sign
    if dollars.startswith('-'):
        sign = '-'
        numeric_part = dollars[1:]
    else:
        sign = '+'
        numeric_part = dollars

    # split into dollars and cents
    if '.' in numeric_part:
        dollars_part, cents_part = numeric_part.split('.', 1)
    else:
        dollars_part = numeric_part
        cents_part = ''

    # pad or truncate cents to exactly 2 digits
    if len(cents_part) == 0:
        cents_part = '00'
    elif len(cents_part) == 1:
        cents_part = cents_part + '0'
    elif len(cents_part) > 2:
        # truncate extra digits (should not happen for valid input, but be safe)
        cents_part = cents_part[:2]

    # combine to minor units (integer cents as string)
    if dollars_part == '' or dollars_part == '0':
        minor_str = cents_part.lstrip('0') or '0'
    else:
        minor_str = dollars_part.lstrip('0') + cents_part

    # if dollars_part was just zeroes, minor_str might be empty or just cents_part
    if not dollars_part or dollars_part.lstrip('0') == '':
        minor_str = str(int(cents_part))  # remove leading zeroes, e.g., "07" -> "7"

    # re-derive clean minor_str from integer to avoid leading zeros
    minor_int = int(dollars_part or '0') * 100 + int(cents_part or '0')
    minor_str = str(minor_int)

    # compute check digit: sum of digits mod 10
    check_digit = sum(int(d) for d in minor_str) % 10

    return f"{sign}{minor_str}#{check_digit}"

