                    "type": "integer",
                    "description": "The amount in cents"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo for the entry"
                }
            },
            "required": ["acct", "cents", "memo"]
        }
    }
]

# Store for simulated ledger entries
ledger_entries = {}
entry_counter = 1


def post(acct: str, cents: int, memo: str) -> str:
    """Simulates posting to a ledger and returns an entry id"""
    global entry_counter
    entry_id = str(entry_counter)
    entry_counter += 1

    ledger_entries[entry_id] = {
        "id": entry_id,
        "account": acct,
        "amount": cents,
        "memo": memo
    }

    return entry_id


def transfer(acct: str, cents: int, reason: str) -> str:
    """Transfer cents to account acct using reason as the memo, and return the entry id"""

    # Use Claude to make the transfer using the post function
    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account '{acct}' with memo '{reason}' and return the entry id."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        # Check if we're done
        if response.stop_reason == "end_turn":
            # Extract the final result from Claude's response
            for block in response.content:
                if hasattr(block, 'text'):
                    # Parse the entry id from Claude's response
                    text = block.text
                    if "entry id" in text.lower():
                        # Try to extract the entry id
                        parts = text.split()
                        for i, part in enumerate(parts):
                            if part.isdigit() and i > 0:
                                return part
                    return text
            break

        # Process tool calls
        if response.stop_reason == "tool_use":
            # Find the tool use block
            tool_use_block = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block and tool_use_block.name == "post":
                # Execute the post function
                result = post(
                    tool_use_block.input["acct"],
                    tool_use_block.input["cents"],
                    tool_use_block.input["memo"]
                )

                # Add the assistant's response and tool result to messages
                messages.append({
                    "role": "assistant",
                    "content": response.content
                })

                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": result
                        }
                    ]
                })
        else:
            # If stop reason is not "tool_use" or "end_turn", break to avoid infinite loop
            break

    # Fallback: directly call post if Claude didn't use the tool
    return post(acct, cents, reason)


# Main execution
if __name__ == "__main__":
    # Test the transfer function
    result = transfer("savings", 15000, "Monthly deposit")
    print(f"Transfer completed with entry id: {result}")
    print(f"Ledger entries: {ledger_entries}")
