def encode_amount(dollars: str) -> str:
    """Serialize a money amount to the team's private wire format."""
    if not isinstance(dollars, str):
        raise TypeError("Amount must be a string")

    # Handle negative amounts
    negative = dollars.startswith('-')
    if negative:
        dollars = dollars[1:]

    # Split into integer and fractional parts
    if '.' in dollars:
        integer_part, fractional_part = dollars.split('.', 1)
        if len(fractional_part) > 2:
            raise ValueError(f"Too many decimal places: {dollars}")
        # Pad fractional part to 2 digits
        fractional_part = fractional_part.ljust(2, '0')
    else:
        integer_part = dollars
        fractional_part = '00'

    # Validate that it's all digits now
    if not integer_part.isdigit():
        raise ValueError(f"Invalid integer part: {integer_part}")
    if not fractional_part.isdigit():
        raise ValueError(f"Invalid fractional part: {fractional_part}")

    # Combine and remove leading zeros from integer part
    integer_part = integer_part.lstrip('0') or '0'
    amount_str = f"{integer_part}.{fractional_part}"

    if negative:
        amount_str = f"-{amount_str}"

    return amount_str

