def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string (e.g. '12.30', '-0.07') to the team's private wire format.

    The format is: sign (1 char) + dollar part as integer string + ':' + cents as 2-digit string
    Example: '12.30' -> '+12:30', '-0.07' -> '-0:07'
    """
    amount_str = dollars.strip()

    # Handle sign
    if amount_str.startswith('-'):
        sign = '-'
        amount_str = amount_str[1:]
    else:
        sign = '+'

    # Split into dollars and cents
    if '.' in amount_str:
        dollars_part, cents_part = amount_str.split('.', 1)
    else:
        dollars_part = amount_str
        cents_part = '00'

    # Validate cents part is exactly 2 digits
    if len(cents_part) == 1:
        cents_part = cents_part + '0'
    elif len(cents_part) > 2:
        raise ValueError(f"Invalid cents length: {cents_part}")

    # Convert dollars part to integer string (removing leading zeros except for zero)
    if dollars_part == '0' or dollars_part == '':
        dollars_int = '0'
    else:
        dollars_int = str(int(dollars_part))

    return f"{sign}{dollars_int}:{cents_part}"

