def encode_amount(dollars: str) -> str:
    """
    Serialize a money amount string (e.g., '12.30', '-0.07') to the team's private wire format.

    The format is: the input string with '.' removed, prepended with 'D' if non-negative,
    or 'M' if negative (the sign is already '-' in the string).
    """
    if dollars.startswith('-'):
        return 'M' + dollars[1:].replace('.', '')
    else:
