def encode_amount(dollars: str) -> str:
    sign = ''
    if dollars.startswith('-'):
        sign = '-'
        dollars = dollars[1:]
    elif dollars.startswith('+'):
        dollars = dollars[1:]

    if '.' in dollars:
        whole, frac = dollars.split('.', 1)
        frac = (frac + '00')[:2]
    else:
        whole, frac = dollars, '00'

    if not whole:
        whole = '0'

    cents = (whole + frac).lstrip('0')
    if not cents:
        cents = '0'

    return sign + cents

