def transfer(acct, cents, reason):
    """
    Transfer funds to an account using the ledger module's post function.

    Args:
        acct: Account name/identifier
        cents: Amount in cents to transfer
        reason: Reason/memo for the transfer

    Returns:
        The entry ID from the ledger post operation
    """

    # Use Claude to call the ledger_post tool
    user_message = f"Post {cents} cents to account '{acct}' with memo '{reason}'. Return the entry ID."

    response = client.messages.create(
        model=MODEL_NAME,
        max_tokens=1024,
        tools=tools,
        messages=[
            {"role": "user", "content": user_message}
        ]
    )

    # Process the response to extract the tool use
    for block in response.content:
        if block.type == "tool_use":
            tool_name = block.name
            tool_input = block.input

            if tool_name == "ledger_post":
                # Simulate the ledger post operation
                # In a real scenario, this would call an actual ledger module
                entry_id = f"entry_{acct}_{tool_input['amount_cents']}_{hash(tool_input['memo']) % 10000}"
                return entry_id

    return None


if __name__ == "__main__":
