        num = raw[1:]
    else:
        sign = "+"
        num = raw[1:] if raw.startswith("+") else raw

    if "." in num:
        dollars_part, cents_part = num.split(".", 1)
        if dollars_part == "":
            dollars_part = "0"
        if len(cents_part) == 0:
            cents_part = "00"
        elif len(cents_part) == 1:
            cents_part = cents_part + "0"
        elif len(cents_part) > 2:
            cents_part = cents_part[:2]
        minor = int(dollars_part) * 100 + int(cents_part)
    else:
        minor = int(num) * 100

    digits = str(minor)
