                }
            },
            "required": ["account", "cents", "memo"]
        }
    }
]

def transfer(acct, cents, reason):
    """
    Transfer funds by posting to the ledger.

    Args:
        acct: The account to post to
        cents: The amount in cents
        reason: The reason/memo for the transaction

    Returns:
        The entry id of the posted transaction
    """
    # Create a message asking Claude to post the transaction
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the reason '{reason}'. Use the post tool to do this."
        }
    ]

    # Call Claude with tools
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    while response.stop_reason == "tool_use":
        # Extract tool use from response
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if not tool_use_block:
            break

        # Get the tool input
        tool_input = tool_use_block.input

        # Simulate the ledger post tool
        # In a real implementation, this would call the actual ledger module
        entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"

        # Add the assistant's response and tool result to messages
        messages.append({"role": "assistant", "content": response.content})
