import anthropic

ledger_code = """
class LedgerEntry:
    def __init__(self, entry_id, account, cents, memo):
        self.entry_id = entry_id
        self.account = account
        self.cents = cents
        self.memo = memo

class Ledger:
    def __init__(self):
        self.entries = []
        self.next_id = 1

    def post(self, account, cents, memo):
        entry = LedgerEntry(self.next_id, account, cents, memo)
        self.entries.append(entry)
        entry_id = self.next_id
        self.next_id += 1
        return entry_id

ledger = Ledger()
"""

client = anthropic.Anthropic()
MODEL_NAME = "claude-3-5-sonnet-20241022"

tools = [
    {
        "name": "ledger_post",
        "description": "Posts a transaction to the ledger with the specified account, amount in cents, and memo",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account name to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["account", "cents", "memo"]
        }
    }
]

exec(ledger_code)

def transfer(acct, cents, reason):
    """
    Transfer cents to account using reason as memo, returns entry id.
    Uses Claude with tool use to interact with the ledger.
    """
    user_message = f"Post {cents} cents to account '{acct}' with reason '{reason}'"

    messages = [
        {"role": "user", "content": user_message}
    ]

    response = client.messages.create(
        model=MODEL_NAME,
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    entry_id = None

    while response.stop_reason == "tool_use":
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if tool_use_block:
            tool_name = tool_use_block.name
            tool_input = tool_use_block.input

            if tool_name == "ledger_post":
                entry_id = ledger.post(
                    account=tool_input["account"],
                    cents=tool_input["cents"],
                    memo=tool_input["memo"]
                )
                tool_result = str(entry_id)
            else:
                tool_result = "Unknown tool"

            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": tool_result
                    }
                ]
            })

            response = client.messages.create(
                model=MODEL_NAME,
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

    return entry_id


if __name__ == "__main__":
    entry_id = transfer("checking", 5000, "salary deposit")
    print(f"Entry ID: {entry_id}")
    print(f"Ledger entries: {[(e.entry_id, e.account, e.cents, e.memo) for e in ledger.entries]}")
