def transfer(acct, cents, reason):
    """
    Transfer funds to an account using the ledger post function.

    Args:
        acct: The account to transfer to
        cents: The amount in cents
        reason: The reason/memo for the transfer

    Returns:
        The entry ID of the posted transaction
    """

    # Create a message to Claude asking it to use the post tool
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the memo '{reason}' using the post tool. Return only the entry ID."
        }
    ]

    # Call Claude with the tools
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response to extract tool use
    entry_id = None

    # Check if Claude wants to use the post tool
    for content_block in response.content:
        if content_block.type == "tool_use" and content_block.name == "post":
            # Extract the tool input
