import operator

import ledger


def _encode_amount(cents):
    value = operator.index(cents)
    sign = "-" if value < 0 else "+"
    digits = str(abs(value))
    check = sum(ord(ch) - ord("0") for ch in digits) % 10
    return f"{sign}{digits}#{check}"


def _entry(acct, amount, note):
    return {"acct": acct, "amount": amount, "note": note}


def record(acct, cents, note):
    amount = _encode_amount(cents)
    post = ledger.post

    try:
        sig = inspect.signature(post)
    except (TypeError, ValueError):
        return post(acct, amount, note)

    params = list(sig.parameters.values())
    has_varargs = any(p.kind is inspect.Parameter.VAR_POSITIONAL for p in params)
    has_varkw = any(p.kind is inspect.Parameter.VAR_KEYWORD for p in params)
    positional = [
        p for p in params
        if p.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD)
    ]

    if has_varargs or len(positional) >= 3:
        return post(acct, amount, note)

    aliases = {
        "acct": {"acct", "account", "account_id"},
        "amount": {"amount", "amt", "cents", "minor_units"},
        "note": {"note", "memo", "description", "desc"},
    }
    values = {"acct": acct, "amount": amount, "note": note}
    kwargs = {}

    for p in params:
        if p.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):
            continue
        lname = p.name.lower()
        for key, names in aliases.items():
            if lname in names:
                kwargs[p.name] = values[key]
                break

    if has_varkw:
        kwargs.setdefault("acct", acct)
        kwargs.setdefault("amount", amount)
        kwargs.setdefault("note", note)

    required = [
        p for p in params
        if p.default is inspect.Parameter.empty
        and p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
    ]

    if kwargs and all(
        p.name in kwargs or p.kind is inspect.Parameter.POSITIONAL_ONLY
        for p in required
    ):
        if not any(p.kind is inspect.Parameter.POSITIONAL_ONLY for p in required):
            return post(**kwargs)

    if len(positional) == 1 and not has_varargs:
        return post(_entry(acct, amount, note))

    return post(acct, amount, note)

