def post(acct, cents, reason):
    # Simulates posting to a ledger
    # In a real system, this would interact with a database
    entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
    return entry_id
"""

def transfer(acct, cents, reason):
    """Transfer cents to account acct with given reason."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "reason": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason '{reason}' using the post function."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use_block = next(
                (block for block in response.content if block.type == "tool_use"),
                None
            )

            if tool_use_block:
                tool_name = tool_use_block.name
                tool_input = tool_use_block.input

                if tool_name == "post":
                    exec(ledger_module)
                    result = post(
                        tool_input["acct"],
                        tool_input["cents"],
                        tool_input["reason"]
                    )

                    messages.append({
                        "role": "assistant",
                        "content": response.content
                    })
                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_use_block.id,
                                "content": str(result)
                            }
                        ]
                    })
        else:
            break

    for block in response.content:
        if block.type == "tool_use" and block.name == "post":
            return block.input.get("acct")

    return None


if __name__ == "__main__":
    entry_id = transfer("12345", 10000, "Test transfer")
    print(f"Transfer completed. Entry ID: {entry_id}")
