import re

_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d*))?|\.(\d+))\s*$")


def _malformed(message: str):
    try:
        import ledger  # type: ignore

        exc_type = getattr(ledger, "PostError")
        try:
            raise exc_type(message)
        except TypeError:
            raise exc_type()
    except ImportError:
        raise ValueError(message)


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _malformed("amount must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        _malformed("malformed amount")

    sign, whole_a, frac_a, frac_b = match.groups()
    whole = whole_a or "0"
    frac = frac_b if frac_b is not None else (frac_a or "")

    if len(frac) > 2:
        _malformed("too many decimal places")

    cents = int(whole) * 100 + int(frac.ljust(2, "0") or "0")
    if sign == "-":
        cents = -cents

    return str(cents)

