    s = dollars.strip()

    if s.startswith("-"):
        sign = "-"
        s = s[1:]
    else:
        sign = "+"
        if s.startswith("+"):
            s = s[1:]

    s = s.replace("$", "")

    if "." in s:
        whole, frac = s.split(".")
    else:
        whole, frac = s, ""

    if not whole:
        whole = "0"

    frac = (frac + "00")[:2]

    digits = (whole + frac).lstrip("0")
    if not digits:
        digits = "0"

    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

