import anthropic
import json


def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer funds using the ledger API via Claude.

    Args:
        acct: Account identifier
        cents: Amount in minor units (cents)
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    # Create tools for Claude to use the ledger API
    tools = [
        {
            "name": "encode_amount",
            "description": "Encodes a monetary amount in cents to the wire format: <sign><digits>#<check>. The check digit is (sum of decimal digits) mod 10.",
            "input_schema": {
                "type": "object",
                "properties": {
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents (can be negative)"
                    }
                },
                "required": ["cents"]
            }
        },
        {
            "name": "post_to_ledger",
            "description": "Posts a transaction to the ledger. Returns the entry id on success.",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "encoded_amount": {
                        "type": "string",
                        "description": "Amount in wire-encoding format: <sign><digits>#<check>"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Memo/reason for the transaction"
                    }
                },
                "required": ["account", "encoded_amount", "memo"]
            }
        }
    ]

    # Helper function to encode amount
    def encode_amount(amount_cents: int) -> str:
        """Encode amount in cents to wire format."""
        sign = '+' if amount_cents >= 0 else '-'
        digits_str = str(abs(amount_cents))
        digit_sum = sum(int(d) for d in digits_str)
        check = digit_sum % 10
        return f"{sign}{digits_str}#{check}"

    # Helper function to call ledger.post
    def post_to_ledger_impl(account: str, encoded_amount: str, memo: str) -> int:
        """Call the actual ledger.post function."""
        # We need to decode the amount from wire format first
        # Extract the sign and digits
        sign_char = encoded_amount[0]
        digits_and_check = encoded_amount[1:]
        digits_str, check_str = digits_and_check.split('#')

        # Reconstruct the amount
        amount_cents = int(digits_str)
        if sign_char == '-':
            amount_cents = -amount_cents

        # Import and call the actual ledger module
        import ledger
        return ledger.post(account, encoded_amount, memo=memo)

    # Call Claude to orchestrate the transfer
    messages = [
        {
            "role": "user",
            "content": f"I need to transfer {cents} cents to account '{acct}' with reason '{reason}'. Please encode the amount and post it to the ledger, then return the entry id."
        }
    ]

    # Agentic loop
    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        # Check if we're done
        if response.stop_reason == "end_turn":
            # Extract the entry id from the response
            for block in response.content:
                if hasattr(block, 'text'):
                    # Try to parse entry id from text
                    text = block.text
                    # Look for patterns like "entry id" or "id:" or just a number
                    import re
                    match = re.search(r'id[:\s]+(\d+)', text.lower())
                    if match:
                        return int(match.group(1))
            break

        # Process tool calls
        if response.stop_reason == "tool_use":
            # Add assistant's response to messages
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            # Process each tool use
            tool_results = []
            for block in response.content:
                if block.type == "tool_use":
                    tool_name = block.name
                    tool_input = block.input

                    # Execute the appropriate tool
                    if tool_name == "encode_amount":
                        result = encode_amount(tool_input["cents"])
                    elif tool_name == "post_to_ledger":
                        try:
                            result = post_to_ledger_impl(
                                tool_input["account"],
                                tool_input["encoded_amount"],
                                tool_input["memo"]
                            )
                        except Exception as e:
                            result = f"Error: {str(e)}"
                    else:
                        result = f"Unknown tool: {tool_name}"

                    tool_results.append({
                        "type": "tool_result",
                        "tool_use_id": block.id,
                        "content": str(result)
                    })

            # Add tool results to messages
            messages.append({
                "role": "user",
                "content": tool_results
            })

    # If we get here, something went wrong
    raise RuntimeError("Failed to complete transfer operation")
