import re

_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$")


def _cents_from_dollars(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        raise ValueError("malformed dollar amount")

    sign, whole, frac, leading_dot_frac = match.groups()

    if leading_dot_frac is not None:
        whole = "0"
        frac = leading_dot_frac
    else:
        frac = frac or ""

    cents = int(whole) * 100 + int(frac.ljust(2, "0"))

    if sign == "-" and cents:
        cents = -cents

    return cents


def encode_amount(dollars: str) -> str:
    return str(_cents_from_dollars(dollars))

