from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar amount string into the ledger wire representation.

    The wire representation is signed integer cents encoded as a decimal string.
    """
    try:
        value = Decimal(dollars)
    except (InvalidOperation, TypeError):
        raise ValueError(f"malformed dollar amount: {dollars!r}")

    cents = (value * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_EVEN)

    if value * Decimal("100") != cents:
        raise ValueError(f"amount has more than two decimal places: {dollars!r}")

    return str(int(cents))

