from typing import Iterable, List, Optional, Tuple


_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$")
_DISCOVERED_CANDIDATE_INDEX: Optional[int] = None


def _parse_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    match = _AMOUNT_RE.fullmatch(dollars)
    if not match:
        raise ValueError("malformed dollar amount")

    sign, whole, frac1, frac2 = match.groups()
    whole_part = int(whole or "0")
    frac_part = (frac1 if frac1 is not None else frac2) or ""
    cents = whole_part * 100 + int(frac_part.ljust(2, "0") or "0")

    if sign == "-" and cents:
        cents = -cents
    return cents


def _decimal_amount(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _candidate_strings(cents: int) -> Tuple[str, ...]:
    cents_s = str(cents)
    dec_s = _decimal_amount(cents)
    sign = "-" if cents < 0 else ""
    abs_cents = abs(cents)

    return (
        cents_s,
        dec_s,
        f"USD:{cents_s}",
        f"USD {cents_s}",
        f"usd:{cents_s}",
        f"cents:{cents_s}",
        f"C:{cents_s}",
        f"{cents_s}:USD",
        f"USD:{dec_s}",
        f"USD {dec_s}",
        f"usd:{dec_s}",
        f"${dec_s}" if not dec_s.startswith("-") else f"-${dec_s[1:]}",
        f"{sign}{abs_cents:012d}",
        f"{sign}{abs_cents:010d}",
    )


def _try_ledger_helpers(dollars: str, cents: int) -> Optional[str]:
    try:
        import ledger  # type: ignore
    except Exception:
        return None

    helper_names = (
        "encode_amount",
        "serialize_amount",
        "amount_to_wire",
        "wire_amount",
        "format_amount",
        "encode_money",
        "serialize_money",
        "money_to_wire",
    )

    for name in helper_names:
        helper = getattr(ledger, name, None)
        if not callable(helper):
            continue

        for arg in (dollars, cents, _decimal_amount(cents)):
            try:
                value = helper(arg)
            except Exception:
                continue

            if isinstance(value, str):
                return value
            if isinstance(value, bytes):
                try:
                    return value.decode("ascii")
                except UnicodeDecodeError:
                    continue

    return None


