    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for key in value.keys():
            if isinstance(key, str):
                yield key
    elif isinstance(value, (list, tuple, set, frozenset)):
        for item in value:
            if isinstance(item, str):
                yield item


