def encode_amount(dollars: str) -> str:
    """Serialize a decimal dollar amount to integer cents string."""
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    negative = dollars.startswith('-')
    if dollars.startswith(('+', '-')):
        dollars = dollars[1:]

    if '.' in dollars:
        if dollars.count('.') != 1:
            raise ValueError("malformed amount")
        whole, fraction = dollars.split('.')
        fraction = (fraction + '00')[:2]
    else:
        whole = dollars
        fraction = '00'

    if not whole:
        whole = '0'

    if not whole.isdigit() or not fraction.isdigit():
        raise ValueError("malformed amount")

    cents = int(whole) * 100 + int(fraction)
    if negative:
        cents = -cents

    return str(cents)

