from decimal import Decimal, InvalidOperation, ROUND_DOWN
import re


_AMOUNT_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d{0,2})?|\.\d{1,2})$")


def _raise_post_error(message: str):
    try:
        import ledger
        exc = ledger.PostError
    except Exception:
        exc = ValueError
    raise exc(message)


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _raise_post_error("malformed amount")

    s = dollars.strip()
    if not _AMOUNT_RE.fullmatch(s):
        _raise_post_error("malformed amount")

    try:
        value = Decimal(s)
    except InvalidOperation:
        _raise_post_error("malformed amount")

    cents_decimal = value * Decimal("100")
    if cents_decimal != cents_decimal.to_integral_value(rounding=ROUND_DOWN):
        _raise_post_error("malformed amount")

    cents = int(cents_decimal)
    return str(cents)

