_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{1,2}))?|\.(\d{1,2}))\s*$")


class _WireAmount(str):
    def __new__(cls, value, cents):
        obj = str.__new__(cls, value)
        obj._cents = cents
        return obj

    def __eq__(self, other):
        if isinstance(other, _WireAmount):
            return self._cents == other._cents
        if isinstance(other, str):
