    Serialize a dollar amount to the team's wire format: signed integer cents
    encoded as a decimal string.
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    cents = (value * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)

    if value * Decimal("100") != cents:
        raise ValueError("amount must have at most two decimal places")

    return str(int(cents))

