def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("too many decimal places")

    frac = frac.ljust(2, "0")
    minor_units = (whole + frac).lstrip("0") or "0"

    if minor_units == "0":
        sign = "+"

    check = sum(int(ch) for ch in minor_units) % 10
    return f"{sign}{minor_units}#{check}"

