import re

_TWO_DECIMAL_RE = re.compile(r'(-)?(\d+)\.(\d{2})')
_INTEGER_RE = re.compile(r'(-)?(\d+)')

def encode_amount(dollars: str) -> str:
    m = _TWO_DECIMAL_RE.fullmatch(dollars)
    if m:
        sign = -1 if m.group(1) else 1
        whole = int(m.group(2))
        frac = int(m.group(3))
        return str(sign * (whole * 100 + frac))

    m = _INTEGER_RE.fullmatch(dollars)
    if m:
        sign = -1 if m.group(1) else 1
        whole = int(m.group(2))
        return str(sign * (whole * 100))

    raise ValueError(f"malformed amount: {dollars}")

