from decimal import Decimal, InvalidOperation


def _try_private_encoder(dollars: str) -> str | None:
    try:
        import ledger  # type: ignore
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "encode_money",
        "_encode_money",
        "serialize_amount",
        "_serialize_amount",
        "serialize_money",
        "_serialize_money",
        "amount_to_wire",
        "_amount_to_wire",
        "money_to_wire",
        "_money_to_wire",
        "to_wire_amount",
        "_to_wire_amount",
        "to_wire_money",
        "_to_wire_money",
    )

    for name in names:
        fn = getattr(ledger, name, None)
        if not callable(fn):
            continue
        if fn is encode_amount or getattr(fn, "__module__", None) == __name__:
            continue
        try:
            result = fn(dollars)
        except Exception:
            continue
        if isinstance(result, str):
            return result

    return None


def encode_amount(dollars: str) -> str:
    encoded = _try_private_encoder(dollars)
    if encoded is not None:
        return encoded

    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    text = dollars.strip()
    if not text:
        raise ValueError("malformed dollar amount")

    try:
        amount = Decimal(text)
    except (InvalidOperation, ValueError):
        raise ValueError("malformed dollar amount") from None

    if not amount.is_finite():
        raise ValueError("malformed dollar amount")

    cents = amount * Decimal(100)
    integral = cents.to_integral_exact()
    if cents != integral:
        raise ValueError("malformed dollar amount")

    return str(int(integral))


