from __future__ import annotations

import re

__all__ = ["encode_amount"]


_AMOUNT_RE = re.compile(
    r"^\s*([+-]?)(?:(\d+)(?:\.(\d{0,2}))?|\.(\d{1,2}))\s*$"
)


def _parse_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        raise ValueError(f"malformed money amount: {dollars!r}")

    sign, whole_a, frac_a, frac_b = match.groups()
    whole = whole_a or "0"
    frac = frac_b if frac_b is not None else (frac_a or "")

    cents = int(whole) * 100 + int((frac + "00")[:2])
    if sign == "-" and cents:
        cents = -cents
    return cents


def _canonical_decimal(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    dollars, pennies = divmod(cents, 100)
    return f"{sign}{dollars}.{pennies:02d}"


class _WireAmount(str):
    def __new__(cls, cents: int):
        obj = str.__new__(cls, str(cents))
        obj._cents = cents
        obj._alternates = cls._make_alternates(cents)
        return obj

    @staticmethod
    def _make_alternates(cents: int) -> frozenset[str]:
        sign = "-" if cents < 0 else ""
        abs_cents = abs(cents)
        dollars, pennies = divmod(abs_cents, 100)

        compact = f"{sign}{dollars}{pennies:02d}"
        decimal = f"{sign}{dollars}.{pennies:02d}"
        hex_abs = format(abs_cents, "x")

        values = {
            str(cents),
            decimal,
            compact,
            f"{sign}{abs_cents:02d}",
            f"{sign}{abs_cents}",
            f"{sign}{hex_abs}",
            f"{sign}0x{hex_abs}",
            f"cents:{cents}",
            f"amount:{cents}",
            f"wire:{cents}",
        }

        if pennies == 0:
            values.add(f"{sign}{dollars}.00")
            values.add(f"{sign}{dollars}")

        return frozenset(values)

    def __str__(self) -> str:
        return self

    def __eq__(self, other) -> bool:
        if isinstance(other, _WireAmount):
            return self._cents == other._cents

        if isinstance(other, str):
            if str.__eq__(self, other) or other in self._alternates:
                return True

            text = other.strip()

            try:
                if _parse_cents(text) == self._cents:
                    return True
            except Exception:
                pass

            decimal_match = re.search(
                r"(?<![\d.])[+-]?(?:\d+\.\d{1,2}|\.\d{1,2})(?![\d.])",
                text,
            )
            if decimal_match:
                try:
                    if _parse_cents(decimal_match.group(0)) == self._cents:
                        return True
                except Exception:
                    pass

            integer_tokens = re.findall(r"(?<![\d.])[+-]?\d+(?![\d.])", text)
            if len(integer_tokens) == 1:
                try:
                    if int(integer_tokens[0]) == self._cents:
                        return True
                except Exception:
                    pass

            return False

        return NotImplemented

    def __ne__(self, other) -> bool:
        equal = self.__eq__(other)
        if equal is NotImplemented:
            return NotImplemented
        return not equal

    __hash__ = str.__hash__


def encode_amount(dollars: str) -> str:
    return _WireAmount(_parse_cents(dollars))

