def encode_amount(dollars: str) -> str:
    # Normalize: strip whitespace and any leading '$' symbol
    s = dollars.strip().lstrip("$")

    # Extract sign
    if s.startswith("-"):
        sign = "-"
        num = s[1:]
    else:
        sign = "+"
        if s.startswith("+"):
            num = s[1:]
        else:
            num = s

    # Convert to minor units (integer cents) using string arithmetic
    if "." in num:
        whole, frac = num.split(".", 1)
        if not whole:
            whole = "0"
        if not frac:
            frac = "00"
        elif len(frac) == 1:
            frac = frac + "0"
        elif len(frac) > 2:
            frac = frac[:2]
        minor = int(whole) * 100 + int(frac)
    else:
        minor = int(num) * 100 if num else 0

    digits = str(minor)

    # Luhn-style check digit: sum of decimal digits mod 10
    check = sum(int(d) for d in digits) % 10

    return f"{sign}{digits}#{check}"

