def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("Empty amount")

    sign = '+'
    if s[0] in '+-':
        sign = s[0]
        s = s[1:]
        if not s:
            raise ValueError("Missing digits after sign")

    if s.startswith('.'):
        s = '0' + s

    if '.' in s:
        whole, frac = s.split('.', 1)
        frac = (frac + '00')[:2]
        cents = int(whole) * 100 + int(frac)
    else:
        cents = int(s) * 100

    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

